/// `encodings.__init__.normalize_encoding`, transcribed:
/// alphanumerics and `.` survive, runs of anything else become a single `_`, and
/// non-ASCII characters are dropped after setting the punctuation flag.
/// Note what the function does **not** do: it never lowercases. Case folding
/// happens in the C fast path inside `codecs.lookup`, so [`search_module`] folds
/// first -- reproducing the interpreter's observable answer, not its Python source.
pub fn normalize_encoding(encoding: &str) -> String {
    let mut chars: Vec<char> = Vec::new();
    let mut punct = false;
    for c in encoding.chars() {
        if c.is_alphanumeric() || c == '.' {
            if punct && !chars.is_empty() {
                chars.push('_');
            }
            if c.is_ascii() {
                chars.push(c);
            }
            punct = false;
        } else {
            punct = true;
        }
    }
    chars.into_iter().collect()
}

/// The module `codecs.lookup(label)` would import, or `None` when CPython would
/// raise `LookupError`. The rule is the interpreter's, measured against
/// `codecs.lookup(...).name` over 1023 spellings (alias keys, module names,
/// canonical names, and web-messy variants of each): fold case, normalize, then
/// the alias table -- including the dotted alias spelling -- then the normalized
/// label itself, then require an importable module.
pub fn search_module(label: &str) -> Option<&'static str> {
    let norm = normalize_encoding(&label.to_lowercase());
    let aliased = look_alias(&norm).or_else(|| look_alias(&norm.replace('.', "_")));
    let mut names: Vec<&str> = Vec::new();
    if let Some(a) = aliased {
        names.push(a);
    }
    names.push(norm.as_str());
    for name in names {
        // CPython skips an empty module name and one that still contains a dot,
        // then imports `encodings.<name>`; only the 118 real modules survive that.
        if name.is_empty() || name.contains('.') {
            continue;
        }
        // Bound to MODULES, not to `norm`, so the answer outlives this call.
        if let Some(module) = MODULES.iter().find(|module| **module == name) {
            return Some(module);
        }
    }
    None
}

fn look_alias(key: &str) -> Option<&'static str> {
    ALIASES
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(_, v)| *v)
}

/// The name `codecs.lookup(label).name` returns, or `None`. This is the observable
/// answer, so the differential truth file can be checked against it directly.
pub fn resolve_codec(label: &str) -> Option<&'static str> {
    let module = search_module(label)?;
    NAME_OF
        .iter()
        .find(|(m, _)| *m == module)
        .map(|(_, name)| *name)
}

/// The carried table for a canonical name.
pub fn charmap_for(name: &str) -> Option<&'static Charmap> {
    CHARMAPS
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, table)| *table)
}

/// Strict single-byte decode: `Err(())` is CPython's `UnicodeDecodeError` for a
/// byte the table has no character for, and there is no lenient shape here -- a
/// table only ever holds one code point per byte.
pub fn decode_single(raw: &[u8], table: &Charmap) -> Result<String, ()> {
    let mut out = String::with_capacity(raw.len());
    for &byte in raw {
        let point = table[usize::from(byte)];
        if point == UNDEFINED {
            return Err(());
        }
        // The sweep proved every carried entry is a single code point, so no
        // surrogate or combining sequence can show up here.
        let ch = char::from_u32(point as u32).ok_or(())?;
        out.push(ch);
    }
    Ok(out)
}

/// Decode bytes under a label, answering the three ways the interpreter can:
/// `None` = "no decoder here" (unknown label, or one this port does not carry),
/// `Some(Err(()))` = the label is real and these bytes are invalid for it,
/// `Some(Ok(text))` = the text.
///
/// The fall-through chain in [`super::resolve::decode_body`] depends on `None` and
/// `Some(Err(()))` being different answers: a codec we do not run must not push the
/// caller toward utf-8 any more than an invalid byte should.
pub fn decode_by_label(raw: &[u8], label: &str) -> Option<Result<String, ()>> {
    let name = resolve_codec(label)?;
    match name {
        "utf-8" => Some(std::str::from_utf8(raw).map(|s| s.to_string()).map_err(|_| ()) ),
        "gbk" => Some(crate::gbk::decode_gbk(raw)),
        "gb2312" => Some(crate::cjk::decode_gb2312(raw)),
        "big5" => Some(crate::cjk::decode_big5(raw)),
        "shift_jis" => Some(crate::cjk::decode_shift_jis(raw)),
        "cp932" => Some(crate::cjk::decode_cp932(raw)),
        other => charmap_for(other).map(|table| decode_single(raw, table)),
    }
}

/// Every label whose decoding this port runs, for tests and for the honest count
/// next to `UNSERVED`: the 78 carried modules answer under 77 distinct names
/// (`iso8859_1` and `latin_1` share one), and the 40 modules here resolve but decline.
pub fn carried(name: &str) -> bool {
    charmap_for(name).is_some()
        || matches!(name, "utf-8" | "gbk" | "gb2312" | "big5" | "shift_jis" | "cp932")
}

